func MPSGraphFromID(id objc.ID) *MPSGraph {
	if id == 0 {
		return nil
	}
	o := &MPSGraph{}
	o.InitPtr(id)
	purego.Track(o)
	return o
}

// Creates a new graph to insert nodes in.
func MPSGraphNew() *MPSGraph {
	_ret := objc.Send[objc.ID](objc.ID(_clsMPSGraph), _mPSGraphSelNew)
	return MPSGraphFromID(_ret)
}

